    $form['contact'] = [
      '#type' => 'details',
      '#title' => $this->t('Contact settings'),
      '#open' => TRUE,
      '#weight' => 5,
    ];
    $account = $form_state->getFormObject()->getEntity();
    if (!$this->currentUser->isAnonymous() && $account->id()) {
      $account_data = $this->userData->get('contact', $account->id(), 'enabled');
    }
